// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        address originalOwner = c.owner();
        bool isCallerOwner = (caller == originalOwner);
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch {}
        address finalOwner = c.owner();
        if (isCallerOwner) {
            assertTrue(finalOwner == newOwner);
        } else {
            assertTrue(finalOwner == originalOwner);
        }
    }
}
